/// Installment + InstallmentPayment models.
/// Mirrors `installments` and `installment_payments` in schema.sql.
/// Money is integer whole PKR. Schedules are generated by
/// `installmentSchedule` in domain/rules.dart.
library;

DateTime? _dt(dynamic v) =>
    v == null ? null : (v is DateTime ? v : DateTime.tryParse(v.toString()));

int _int(dynamic v) => (v as num?)?.toInt() ?? 0;

/// One due installment row (`installment_payments` table).
class InstallmentPayment {
  final String id;
  final String installmentId;
  final DateTime dueDate;
  final int amount;
  final int paidAmount;
  final DateTime? paidDate;

  /// `pending` | `partial` | `paid` | `overdue`.
  final String status;
  final bool reminderSent;
  final DateTime createdAt;
  final DateTime updatedAt;

  const InstallmentPayment({
    required this.id,
    required this.installmentId,
    required this.dueDate,
    required this.amount,
    this.paidAmount = 0,
    this.paidDate,
    this.status = 'pending',
    this.reminderSent = false,
    required this.createdAt,
    required this.updatedAt,
  });

  /// Amount still owed on this row.
  int get remaining => amount - paidAmount;

  factory InstallmentPayment.fromJson(Map<String, dynamic> json) =>
      InstallmentPayment(
        id: json['id'] as String,
        installmentId: json['installment_id'] as String,
        dueDate: _dt(json['due_date']) ?? DateTime.now(),
        amount: _int(json['amount']),
        paidAmount: _int(json['paid_amount']),
        paidDate: _dt(json['paid_date']),
        status: json['status'] as String? ?? 'pending',
        reminderSent: json['reminder_sent'] as bool? ?? false,
        createdAt: _dt(json['created_at']) ?? DateTime.now(),
        updatedAt: _dt(json['updated_at']) ?? DateTime.now(),
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'installment_id': installmentId,
        'due_date': dueDate.toIso8601String(),
        'amount': amount,
        'paid_amount': paidAmount,
        'paid_date': paidDate?.toIso8601String(),
        'status': status,
        'reminder_sent': reminderSent,
        'created_at': createdAt.toIso8601String(),
        'updated_at': updatedAt.toIso8601String(),
      };

  InstallmentPayment copyWith({
    String? id,
    String? installmentId,
    DateTime? dueDate,
    int? amount,
    int? paidAmount,
    DateTime? paidDate,
    String? status,
    bool? reminderSent,
    DateTime? createdAt,
    DateTime? updatedAt,
  }) =>
      InstallmentPayment(
        id: id ?? this.id,
        installmentId: installmentId ?? this.installmentId,
        dueDate: dueDate ?? this.dueDate,
        amount: amount ?? this.amount,
        paidAmount: paidAmount ?? this.paidAmount,
        paidDate: paidDate ?? this.paidDate,
        status: status ?? this.status,
        reminderSent: reminderSent ?? this.reminderSent,
        createdAt: createdAt ?? this.createdAt,
        updatedAt: updatedAt ?? this.updatedAt,
      );

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is InstallmentPayment &&
          other.id == id &&
          other.installmentId == installmentId &&
          other.dueDate == dueDate &&
          other.amount == amount &&
          other.paidAmount == paidAmount &&
          other.status == status;

  @override
  int get hashCode =>
      Object.hash(id, installmentId, dueDate, amount, paidAmount, status);
}

/// An installment plan for one sale (`installments` table).
class Installment {
  final String id;
  final String saleId;
  final String customerId;
  final int totalAmount;
  final int downPayment;
  final int installmentCount;
  final int installmentAmount;
  final DateTime startDate;

  /// `active` | `completed` | `defaulted`.
  final String status;
  final DateTime createdAt;
  final DateTime updatedAt;

  /// The plan's due rows (not a column).
  final List<InstallmentPayment> payments;

  const Installment({
    required this.id,
    required this.saleId,
    required this.customerId,
    required this.totalAmount,
    this.downPayment = 0,
    required this.installmentCount,
    required this.installmentAmount,
    required this.startDate,
    this.status = 'active',
    required this.createdAt,
    required this.updatedAt,
    this.payments = const [],
  });

  /// Amount still owed across all rows.
  int get remainingAmount =>
      payments.fold<int>(0, (sum, p) => sum + p.remaining);

  factory Installment.fromJson(Map<String, dynamic> json) => Installment(
        id: json['id'] as String,
        saleId: json['sale_id'] as String,
        customerId: json['customer_id'] as String,
        totalAmount: _int(json['total_amount']),
        downPayment: _int(json['down_payment']),
        installmentCount: _int(json['installment_count']),
        installmentAmount: _int(json['installment_amount']),
        startDate: _dt(json['start_date']) ?? DateTime.now(),
        status: json['status'] as String? ?? 'active',
        createdAt: _dt(json['created_at']) ?? DateTime.now(),
        updatedAt: _dt(json['updated_at']) ?? DateTime.now(),
        payments: (json['payments'] as List?)
                ?.map((e) =>
                    InstallmentPayment.fromJson(e as Map<String, dynamic>))
                .toList() ??
            const [],
      );

  Map<String, dynamic> toJson() => {
        'id': id,
        'sale_id': saleId,
        'customer_id': customerId,
        'total_amount': totalAmount,
        'down_payment': downPayment,
        'installment_count': installmentCount,
        'installment_amount': installmentAmount,
        'start_date': startDate.toIso8601String(),
        'status': status,
        'created_at': createdAt.toIso8601String(),
        'updated_at': updatedAt.toIso8601String(),
        'payments': payments.map((e) => e.toJson()).toList(),
      };

  Installment copyWith({
    String? id,
    String? saleId,
    String? customerId,
    int? totalAmount,
    int? downPayment,
    int? installmentCount,
    int? installmentAmount,
    DateTime? startDate,
    String? status,
    DateTime? createdAt,
    DateTime? updatedAt,
    List<InstallmentPayment>? payments,
  }) =>
      Installment(
        id: id ?? this.id,
        saleId: saleId ?? this.saleId,
        customerId: customerId ?? this.customerId,
        totalAmount: totalAmount ?? this.totalAmount,
        downPayment: downPayment ?? this.downPayment,
        installmentCount: installmentCount ?? this.installmentCount,
        installmentAmount: installmentAmount ?? this.installmentAmount,
        startDate: startDate ?? this.startDate,
        status: status ?? this.status,
        createdAt: createdAt ?? this.createdAt,
        updatedAt: updatedAt ?? this.updatedAt,
        payments: payments ?? this.payments,
      );

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is Installment &&
          other.id == id &&
          other.saleId == saleId &&
          other.customerId == customerId &&
          other.totalAmount == totalAmount &&
          other.status == status;

  @override
  int get hashCode =>
      Object.hash(id, saleId, customerId, totalAmount, status);
}
